AcceptanceCriteria.AC-BASE-BYTE-INVARIANT:
        Relative to preservation base `4d4c837cacc59ba59a44dcb7bf708a3404ab2e3c`, every base-tracked
        path outside the exact six product files and this bundle's exact own active/archive lifecycle
        directories is byte/type/Git-mode identical, and no deleted or newly tracked path exists outside
        that allowed set. The instrument scans all base-tracked paths including both archive trees,
        checks the actual filesystem raw bytes and type/Git-mode against the base for every one of them
        — so a byte edited under `--assume-unchanged` or `--skip-worktree` still fails — and checks both
        unstaged and cached changes. Arbitrary untracked files outside the archive trees are not a new
        scope claim. It reads the exit code directly, never through a pipe, and fails closed on a
        missing base or a failed Git or filesystem read.
        git diff --exit-code 4d4c837cacc59ba59a44dcb7bf708a3404ab2e3c -- . ':(exclude)skills/ngrace/ngrace-plan/SKILL.md' ':(exclude)plugins/ngrace/skills/ngrace/ngrace-plan/SKILL.md' ':(exclude)scripts/check-teaching-surface.ts' ':(exclude)scripts/check-teaching-surface.test.ts' ':(exclude)src/test-support/token-accounting.test.ts' ':(exclude)README.md' ':(exclude).ngrace/changes/active/C-PLANNING-PHASE-TEACHING-2-10CC89CA' ':(exclude).ngrace/changes/archive/C-PLANNING-PHASE-TEACHING-2-10CC89CA' && git diff --cached --exit-code 4d4c837cacc59ba59a44dcb7bf708a3404ab2e3c -- . ':(exclude)skills/ngrace/ngrace-plan/SKILL.md' ':(exclude)plugins/ngrace/skills/ngrace/ngrace-plan/SKILL.md' ':(exclude)scripts/check-teaching-surface.ts' ':(exclude)scripts/check-teaching-surface.test.ts' ':(exclude)src/test-support/token-accounting.test.ts' ':(exclude)README.md' ':(exclude).ngrace/changes/active/C-PLANNING-PHASE-TEACHING-2-10CC89CA' ':(exclude).ngrace/changes/archive/C-PLANNING-PHASE-TEACHING-2-10CC89CA' && bun -e 'const {spawnSync}=require("node:child_process");
const fs=require("node:fs");
const crypto=require("node:crypto");
const BASE="4d4c837cacc59ba59a44dcb7bf708a3404ab2e3c";
const OWN="C-PLANNING-PHASE-TEACHING-2-10CC89CA";
const ALLOWED=new Set(["skills/ngrace/ngrace-plan/SKILL.md","plugins/ngrace/skills/ngrace/ngrace-plan/SKILL.md","scripts/check-teaching-surface.ts","scripts/check-teaching-surface.test.ts","src/test-support/token-accounting.test.ts","README.md"]);
function fail(msg){console.error("GUARD-B FAIL: "+msg);process.exit(1);}
function dep(cmd,args){const r=spawnSync(cmd,args,{encoding:"buffer"});if(r.error){fail("dependency error "+cmd+": "+r.error.message);}if(r.status!==0){fail("dependency exit "+r.status+" "+cmd+" "+args.join(" ")+" :: "+r.stderr.toString().trim());}return r.stdout;}
function contentOf(p){const st=fs.lstatSync(p);if(st.isSymbolicLink())return Buffer.from(fs.readlinkSync(p));return fs.readFileSync(p);}
function blobSha(buf){return crypto.createHash("sha1").update(Buffer.concat([Buffer.from("blob "+buf.length+"\0"),buf])).digest("hex");}
function isOwn(p){const a=".ngrace/changes/active/"+OWN;const b=".ngrace/changes/archive/"+OWN;return p===a||p.startsWith(a+"/")||p===b||p.startsWith(b+"/");}
function allowed(p){return ALLOWED.has(p)||isOwn(p);}
const baseRaw=dep("git",["ls-tree","-r","-z",BASE]).toString("utf8");
const base=new Map();
for(const rec of baseRaw.split("\0")){if(rec.length===0)continue;const tab=rec.indexOf("\t");const meta=rec.slice(0,tab).split(" ");base.set(rec.slice(tab+1),{mode:meta[0],sha:meta[2]});}
const cur=dep("git",["ls-files","-z"]).toString("utf8").split("\0").filter(s=>s.length>0);
const curSet=new Set(cur);
const bad=[];
for(const [p,entry] of base){if(allowed(p))continue;if(!curSet.has(p)){bad.push("deleted "+p);continue;}let b;try{const st=fs.lstatSync(p);const mode=st.isSymbolicLink()?"120000":st.isFile()?((st.mode&0o100)?"100755":"100644"):"invalid";if(mode!==entry.mode){bad.push("mode/type "+p);continue;}b=contentOf(p);}catch(e){bad.push("unreadable "+p);continue;}if(blobSha(b)!==entry.sha)bad.push("byte "+p);}
for(const p of cur){if(allowed(p))continue;if(!base.has(p))bad.push("extra-tracked "+p);}
if(bad.length){fail(bad.slice(0,30).join("; "));}
console.log("GUARD-B OK tracked="+curSet.size);'

AcceptanceCriteria.AC-ARCHIVE-PRESERVATION:
        Every pre-existing byte and every pre-existing root/path under `.ngrace/changes/archive/` and
        `docs/plans/archive/` is unchanged against preservation base
        `4d4c837cacc59ba59a44dcb7bf708a3404ab2e3c`. Because Git cannot track an empty directory, the
        criterion also seals the exact measured filesystem-only inventory of eighteen empty archive
        `run/` directories: each must exist as a real non-symlink directory with captured mode `0755`
        and remain empty. The instrument inventories the base Git paths and blob bytes and the actual
        filesystem entries under both archive trees, rejecting a missing, changed, or extra path, an
        ignored or untracked addition, and an added or missing root; it compares raw bytes and
        Git modes, root/path inventories, and sealed-directory type, captured mode, and emptiness; it never parses XML, schema, or content. It skips exactly this bundle's own
        `.ngrace/changes/archive/C-PLANNING-PHASE-TEACHING-2-10CC89CA` arrival, with the reason that the
        close itself renames the bundle directory into the archive and writes that arrived bundle's own
        post-archive verdict and `CloseEvidence`, so without the exclusion the close's own lawful arrival
        reddens the criterion it wrote; the predecessor's archive arrival is inside the preservation
        base and needs no exclusion, and `docs/plans/archive/` has no exclusion. It retains the
        `git diff` guard and fails closed on a missing base or a failed Git or filesystem read.
        git diff --exit-code 4d4c837cacc59ba59a44dcb7bf708a3404ab2e3c -- .ngrace/changes/archive docs/plans/archive ':(exclude).ngrace/changes/archive/C-PLANNING-PHASE-TEACHING-2-10CC89CA' && bun -e 'const {spawnSync}=require("node:child_process");
const fs=require("node:fs");
const path=require("node:path");
const crypto=require("node:crypto");
const BASE = "4d4c837cacc59ba59a44dcb7bf708a3404ab2e3c";
const OWN = "C-PLANNING-PHASE-TEACHING-2-10CC89CA";
const ARCHS = [".ngrace/changes/archive", "docs/plans/archive"];
const SEALED_EMPTY_DIRS = [
  ".ngrace/changes/archive/C-ARCHIVE-CORPUS-BASELINE-2-D5F2E1C3/run",
  ".ngrace/changes/archive/C-COORDINATOR-BOUNDARY-1-CB86E900/run",
  ".ngrace/changes/archive/C-CURRENT-VALIDATION-BOUNDARY-1-D8D7DF85/run",
  ".ngrace/changes/archive/C-DECLARATION-GUARD-RETIRE-1-C69B6AB6/run",
  ".ngrace/changes/archive/C-GENERIC-REVIEW-SCOPE-1-A7E352BF/run",
  ".ngrace/changes/archive/C-GENERIC-SHAPE-DATA-1-11D2BE52/run",
  ".ngrace/changes/archive/C-HISTORICAL-ASSERTION-REVIEW-4-5D40885D/run",
  ".ngrace/changes/archive/C-INODE-EVIDENCE-REMOVAL-1-49104F3E/run",
  ".ngrace/changes/archive/C-MINT-BASELINE-CONTROL-2-C2E3D3A3/run",
  ".ngrace/changes/archive/C-MINT-BASELINE-CONTROL-3-F04434E4/run",
  ".ngrace/changes/archive/C-PLAN-INDEX-ALIGNMENT-1-479FBC5C/run",
  ".ngrace/changes/archive/C-PLANNING-PHASE-TEACHING-1-CBE5DFAD/run",
  ".ngrace/changes/archive/C-PREPIN-CI-RETIREMENT-1-D5867E60/run",
  ".ngrace/changes/archive/C-REVIEW-CURRENT-BOUNDARY-2-6ACE9713/run",
  ".ngrace/changes/archive/C-REVIEW-PAIR-FIXTURES-1-429BFA80/run",
  ".ngrace/changes/archive/C-SELECTED-CLOSE-BOUNDARY-1-7CADD2ED/run",
  ".ngrace/changes/archive/C-SQUASH-WITNESS-1-87D77A3D/run",
  ".ngrace/changes/archive/C-SQUASH-WITNESS-4-E1A787BF/run"
];
const bad = [];
function fail(message) { console.error(`GUARD-A FAIL: ${message}`); process.exit(1); }
function dep(command, args) {
  const result = spawnSync(command, args, { encoding: "buffer" });
  if (result.error) fail(`dependency error ${command}: ${result.error.message}`);
  if (result.status !== 0) fail(`dependency exit ${result.status} ${command} ${args.join(" ")} :: ${result.stderr.toString().trim()}`);
  return result.stdout;
}
function isOwn(p) {
  const own = `${ARCHS[0]}/${OWN}`;
  return p === own || p.startsWith(`${own}/`);
}
function readNode(p) {
  const st = fs.lstatSync(p);
  if (st.isSymbolicLink()) return Buffer.from(fs.readlinkSync(p));
  if (st.isFile()) return fs.readFileSync(p);
  throw new Error(`unsupported file type ${p}`);
}
function blobSha(bytes) {
  return crypto.createHash("sha1").update(Buffer.concat([Buffer.from(`blob ${bytes.length}\0`), bytes])).digest("hex");
}
for (const ARCH of ARCHS) {
  const raw = dep("git", ["ls-tree", "-r", "-z", BASE, "--", ARCH]).toString("utf8");
  const base = new Map();
  const baseRoots = new Set();
  const baseDirs = new Set();
  for (const rec of raw.split("\0")) {
    if (!rec) continue;
    const tab = rec.indexOf("\t");
    const meta = rec.slice(0, tab);
    const p = rec.slice(tab + 1);
    const [mode, type, sha] = meta.split(" ");
    base.set(p, { mode, type, sha });
    let prefix = ARCH;
    for (const part of p.slice(ARCH.length + 1).split("/").slice(0, -1)) {
      prefix += `/${part}`;
      baseDirs.add(prefix);
    }
    const first = p.slice(ARCH.length + 1).split("/")[0];
    if (first) baseRoots.add(first);
  }
  const rootPath = ARCH;
  try {
    if (!fs.lstatSync(rootPath).isDirectory()) bad.push(`root-not-directory ${rootPath}`);
  } catch { bad.push(`root-missing ${rootPath}`); continue; }
  for (const [p, item] of base) {
    if (isOwn(p)) continue;
    let bytes;
    try { bytes = readNode(p); } catch { bad.push(`missing-or-unreadable ${p}`); continue; }
    if (blobSha(bytes) !== item.sha) bad.push(`byte ${p}`);
    const st = fs.lstatSync(p);
    const actualMode = st.isSymbolicLink() ? "120000" : ((st.mode & 0o111) !== 0 ? "100755" : "100644");
    if (item.mode !== actualMode) bad.push(`mode ${p}`);
  }
  const actualFiles = [];
  function walk(directory) {
    for (const name of fs.readdirSync(directory)) {
      const p = path.join(directory, name).split(path.sep).join("/");
      if (isOwn(p)) continue;
      let st;
      try { st = fs.lstatSync(p); } catch { bad.push(`unreadable ${p}`); continue; }
      if (st.isDirectory()) {
        if (!baseDirs.has(p) && !SEALED_EMPTY_DIRS.includes(p)) bad.push(`extra-directory ${p}`);
        walk(p);
      } else {
        actualFiles.push(p);
      }
    }
  }
  walk(rootPath);
  for (const p of actualFiles) if (!base.has(p)) bad.push(`extra ${p}`);
  const actualRoots = new Set();
  for (const name of fs.readdirSync(rootPath)) {
    const p = `${rootPath}/${name}`;
    if (isOwn(p)) continue;
    actualRoots.add(name);
  }
  for (const name of baseRoots) if (!actualRoots.has(name)) bad.push(`root-missing ${name}`);
  for (const name of actualRoots) if (!baseRoots.has(name)) bad.push(`root-extra ${name}`);
}
for (const p of SEALED_EMPTY_DIRS) {
  let st;
  try { st = fs.lstatSync(p); } catch { bad.push(`sealed-directory-missing ${p}`); continue; }
  if (!st.isDirectory() || st.isSymbolicLink()) { bad.push(`sealed-directory-type ${p}`); continue; }
  if ((st.mode & 0o7777) !== 0o755) bad.push(`sealed-directory-mode ${p}`);
  try { if (fs.readdirSync(p).length !== 0) bad.push(`sealed-directory-populated ${p}`); }
  catch { bad.push(`sealed-directory-unreadable ${p}`); }
}
const gitDiff = spawnSync("git", ["diff", "--exit-code", BASE, "--", ".ngrace/changes/archive", "docs/plans/archive", `:(exclude).ngrace/changes/archive/${OWN}`], { encoding: "utf8" });
if (gitDiff.error || gitDiff.status !== 0) bad.push(`git-diff ${gitDiff.status}: ${(gitDiff.stderr ?? "").trim()}`);
if (bad.length) fail(bad.slice(0, 30).join("; "));
console.log(`GUARD-A OK archives=${ARCHS.length} sealed-empty-directories=${SEALED_EMPTY_DIRS.length}`);'
